class Spring {
  constructor(stiffness, damping, mass, initialValue, maxVelocity) {
    this.stiffness = stiffness; this.damping = damping; this.mass = mass;
    this.position = initialValue; this.velocity = 0; this.maxVelocity = maxVelocity;
  }
  update(target, deltaTime) {
    const force = -this.stiffness * (this.position - target);
    const dampingForce = -this.damping * this.velocity;
    const acceleration = (force + dampingForce) / this.mass;
    this.velocity += acceleration * deltaTime;
    this.velocity = constrain(this.velocity, -this.maxVelocity, this.maxVelocity);
    this.position += this.velocity * deltaTime;
    return this.position;
  }
}

function easeOutCubic(t){ return 1 - pow(1 - t, 3); }
function limitedLerp(current, target, maxDelta) {
  let diff = target - current;
  if(abs(diff) > maxDelta) return current + (diff > 0 ? maxDelta : -maxDelta);
  else return target;
}

