}

function drawFullscreenTriangles(ctx, usePushPop){
  if(usePushPop){ ctx.push(); ctx.resetMatrix(); }
  ctx.beginShape(TRIANGLES);
  ctx.vertex(-1, -1, 0); ctx.vertex( 1, -1, 0); ctx.vertex( 1,  1, 0);
  ctx.vertex(-1, -1, 0); ctx.vertex( 1,  1, 0); ctx.vertex(-1,  1, 0);
  ctx.endShape();
  if(usePushPop){ ctx.pop(); }
}

