function randomizeParameters() {

  const ranges = {
    fractalScale:      [1.0,   5.0],
    fractalOffset:     [0.0,   0.8],      
    rotationAngle:     [0.434, 5.849],    
    rotationVariation: [0.0,   1.0],
    scaleVariation:    [0.0,   1.0],
    wrapBlend:         [0.0,   1.0],
    noiseStrength:     [0.0,   1.0],
    noiseScale:        [0.1,   10.0],
    foldAngle:         [0.0,   TWO_PI],
    foldCount:         [1,     6],
    sphericalAmount:   [0.0,   0.5],
    swirlStrength:     [0.0,   0.5],
    polarPower:        [0.5,   2.5],
    horseshoeAmount:   [0.0,   0.5]
  };

  const params = Object.keys(ranges);

  params.forEach(param => {

    if (!advancedFeaturesUnlocked && lockedParameterNames.includes(param)) return;

    const [min, max] = ranges[param];
    const val = random(min, max);
    window[param] = val;  

    switch (param) {
      case 'fractalOffset':
        offsetSpring.position = val;
        offsetSpring.velocity = 0;
        sm_fractalOffset = val;
        break;
      case 'rotationAngle':
        rotationSpring.position = val;
        rotationSpring.velocity = 0;
        sm_rotationAngle = val;
        break;
      case 'rotationVariation':
        rotationVarSpring.position = val;
        rotationVarSpring.velocity = 0;
        sm_rotationVariation = val;
        break;
      case 'fractalScale':
        sm_fractalScale   = val;
        break;
      case 'scaleVariation':
        sm_scaleVariation = val;
        break;
      case 'wrapBlend':
        sm_wrapBlend      = val;
        break;
      case 'noiseStrength':
        sm_noiseStrength  = val;
        break;
      case 'noiseScale':
        sm_noiseScale     = val;
        break;

		case 'foldAngle':
        sm_foldAngle = val;
        break;
      case 'foldCount':
        sm_foldCount = Math.round(val);
        break;
      case 'sphericalAmount':
        sm_sphericalAmount = val;
        break;
      case 'swirlStrength':
        sm_swirlStrength = val;
        break;
      case 'polarPower':
        sm_polarPower = val;
        break;
      case 'horseshoeAmount':
        sm_horseshoeAmount = val;
        break;

    }

    updateOPCControl(param, val);
  });
}

