function generateMathString(){
  let tileDesc;
  if(tileMethod==0){
    tileDesc="Square Tiling:\n  p = mod(p,2) − 1 with edge mirroring controlled by wrapBlend";
  } else if(tileMethod==1){
    tileDesc="Seamless Mirroring:\n  p = mix( abs(mod(p,2)−1)*2 − 1, sin(p), wrapBlend )";
  } else if(tileMethod==2){
    tileDesc="Infinite Tile:\n  p remains unchanged";
  } else if(tileMethod==3){
    tileDesc="Toroidal Tiling:\n  p = periodicMap2(p)";
  } else if(tileMethod==4){
    tileDesc="Hex Tiling:\n  Map p into a hexagonal lattice using axial coordinate conversion";
  } else if(tileMethod==5){
    tileDesc="Triangular Tiling:\n  Partition p into equilateral triangles using modulo and reflection";
  } else if(tileMethod==6){
    tileDesc="Spiral Tiling:\n  Convert p to polar coords, adjust theta with log(r)*spiralFactor, then convert back";
  } else {
    tileDesc="Tiling method unknown.";
  }
  let s="";
  s+="===== Fractal Mathematical Blueprint =====\n\n";
  s+="Let N = "+fractalIterations+"  // Number of iterations\n\n";
  s+="For each iteration i (0 ≤ i < N):\n";
  s+="  1. Start with a point p_i ∈ ℝ² (normalized coords).\n";
  s+="  2. N-fold symmetry folding (foldCount = "+foldCount+"):\n";
  s+="        θ = atan2(p.y, p.x)\n";
  s+="        segment = 2π / "+foldCount+"\n";
  s+="        θ' = mod(θ + "+nf(foldAngle,1,3)+", segment)\n";
  s+="        if θ' > segment/2: θ' = segment - θ'\n";
  s+="        p = r × (cos(θ'), sin(θ'))\n";
  s+="  3. Apply absolute value: p' = |p_i| (component-wise).\n";
  s+="  4. Scale the point:\n";
  s+="        p'' = "+fractalScale+" × [1 + "+nf(scaleVariation,1,2)+"·i] × p'\n";
  s+="  5. Tiling transformation (tileMethod):\n";
  s+="       "+tileDesc+"\n";
  s+="  6. Spherical inversion blend (amount = "+nf(sphericalAmount,1,2)+"):\n";
  s+="        p_sph = p / |p|²\n";
  s+="        p = mix(p, p_sph, "+nf(sphericalAmount,1,2)+")\n";
  s+="  7. Swirl transformation (strength = "+nf(swirlStrength,1,2)+"):\n";
  s+="        θ = atan2(p.y, p.x) + "+nf(swirlStrength,1,2)+" × |p|\n";
  s+="        p = |p| × (cos(θ), sin(θ))\n";
  s+="  8. Polar power (power = "+nf(polarPower,1,2)+"):\n";
  s+="        r = |p|^"+nf(polarPower,1,2)+"\n";
  s+="        p = r × (cos(θ), sin(θ))\n";
  s+="  9. Horseshoe blend (amount = "+nf(horseshoeAmount,1,2)+"):\n";
  s+="        p_horse = (1/r) × ((x−y)(x+y), 2xy)\n";
  s+="        p = mix(p, p_horse, "+nf(horseshoeAmount,1,2)+")\n";
  s+=" 10. Rotate:\n";
  s+="        d = "+rotationAngle+" × [1 + "+nf(rotationVariation,1,2)+"·i]\n";
  s+="        p_r = Rotate(p, d)\n";
  s+=" 11. Offset + warp:\n";
  s+="        p_o = p_r + "+fractalOffset+"\n";
  s+="        p_w = mix(p_o, sin(p_o), "+warpIntensity+")\n\n";
  s+="Accumulate intensity:\n";
  s+="  I_total = Σ[i=0..N-1] [1 − smoothstep(0, 0.5, ||p_w||)]\n";
  s+="  I_avg = I_total / N\n\n";
  s+="Color Composition:\n";
  s+="  FinalColor = mix("+bgColor+", mix("+color1+", "+color2+", I_avg), 1 − I_avg)\n";
  s+="============================================";
  return s;
}


function toggleAnimate(){
  if(!animateMode){
    if(!soundFile){ fileInput.elt.value=''; fileInput.elt.click(); }
    else{
      soundFile.play(); animateMode=true; updateOPCButtonText('animateButton','Stop Animate');
    }
  } else {
    animateMode=false; updateOPCButtonText('animateButton','Animate');
    if(soundFile){
      if(soundFile.isPlaying()) soundFile.stop();
      if(typeof soundFile.dispose==='function') soundFile.dispose();
      soundFile=null; amplitude=null;
    }
  }
}

function handleFile(file){
  if(file.type==='audio'){
    if(soundFile && soundFile.isPlaying()) soundFile.stop();
    loadSound(file.data,soundLoaded,soundLoadError);
  } else { alert("Please select a valid audio file."); }
}

function soundLoaded(loadedSound){
  soundFile=loadedSound; soundFile.play(); amplitude=new p5.Amplitude(); amplitude.setInput(soundFile);
  baseFractalOffset=fractalOffset; baseRotationAngle=rotationAngle; baseWarpIntensity=warpIntensity; baseRotationVariation=rotationVariation;
  animateMode=true; updateOPCButtonText('animateButton','Stop Animate');
  soundFile.onended(()=>{
    if(soundFile){
      animateMode=false; updateOPCButtonText('animateButton','Animate');
      soundFile.dispose(); soundFile=null; amplitude=null;
    }
  });
}

