function exportPreset() {
  let presetName = prompt("Enter preset name:", "My Preset");
  if (presetName === null || presetName.trim() === "") {

    return;
  }

  try {
    redraw();
    let currentCanvas = get();

    if (!currentCanvas) {

        alert("Error: Could not generate preset thumbnail.");
        return;
    }

    const thumbWidth = 160, thumbHeight = 120;
    let thumbBuffer = createGraphics(thumbWidth, thumbHeight);
    thumbBuffer.image(currentCanvas, 0, 0, thumbWidth, thumbHeight);
    let thumbnailData = thumbBuffer.canvas.toDataURL("image/png");
    thumbBuffer.remove();

    let preset = { name: presetName, params: {}, thumbnail: thumbnailData };
    presetParameterNames.forEach(param => {
      let valueToSave = undefined;
      let found = false;

      if (lockedParameterNames.includes(param) && advancedFeaturesUnlocked === false) {
          switch (param) {
              case 'fractalScale':    valueToSave = preset_fractalScale; break;
              case 'scaleVariation':  valueToSave = preset_scaleVariation; break;
              case 'wrapBlend':       valueToSave = preset_wrapBlend; break;
              case 'noiseStrength':   valueToSave = preset_noiseStrength; break;
              case 'noiseScale':      valueToSave = preset_noiseScale; break;
          }
          found = true;
      } else {
          if (typeof window[param] !== 'undefined') {
              valueToSave = window[param];
              found = true;
          }
          else if (param === 'zoomFactor' && typeof zoomFactor !== 'undefined') {
              valueToSave = zoomFactor;
              found = true;
          }
      }

      if (found) {
          preset.params[param] = valueToSave;
      } else {

      }
    });

    var filename = presetName.replace(/[^a-z0-9_]/gi, '_').replace(/_{2,}/g, '_') + "_" + Date.now() + ".json";
    saveJSON(preset, filename);

    setTimeout(() => {
       var existingIndex = loadedPresets.findIndex(p => p.name === preset.name);
       if (existingIndex !== -1) {

       } else {
           loadedPresets.push(preset);
       }
       updatePresetListUI();

    }, 0);

  } catch (error) {

    alert("An error occurred while saving the preset: " + error.message);
  }
}

function handlePresetFiles(files) { 
  if (Array.isArray(files)) {
    files.forEach(processSinglePreset);
  } else if (files) { 
    processSinglePreset(files); 
  }
  updatePresetListUI(); 
}

function processSinglePreset(file) {

  if (!file || !(file.subtype === "json" || file.type === "application/json") || !file.data) {

      return; 
  }

  try {

    var preset = (typeof file.data === "string") ? JSON.parse(file.data) : file.data;

    if (preset && preset.params && preset.thumbnail && preset.name) {

      var existingIndex = loadedPresets.findIndex(p => p.name === preset.name);
      if (existingIndex === -1) {
        loadedPresets.push(preset);

      } else {

      }

    } else {
      alert("Invalid preset file structure: " + file.name);

    }
  } catch (e) {
    alert("Error parsing preset file: " + file.name + "\nError: " + e.message);

  }
}

