function loadPreset(preset) {
  if (!preset || !preset.params) {

    alert("Error: Could not load invalid preset data.");
    return;
  }

  isApplyingPreset = true;              

  const loadedKeys = new Set(Object.keys(preset.params));

  for (let key in preset.params) {
    if (!preset.params.hasOwnProperty(key)) continue;
    let value = preset.params[key];
    if (['zoomFactor','fractalOffset','rotationAngle','warpIntensity','rotationVariation'].includes(key)) {
      continue; 
    }
    if (presetParameterNames.includes(key)) {
      window[key] = value;
      updateOPCControl(key, value);

      if (key === 'color1')    sm_color1 = hexToRgb(value);
      else if (key === 'color2') sm_color2 = hexToRgb(value);
      else if (key === 'bgColor') sm_bgColor = hexToRgb(value);
      else if (key === 'fractalScale') { preset_fractalScale = value; sm_fractalScale = value; }
      else if (key === 'scaleVariation') { preset_scaleVariation = value; sm_scaleVariation = value; }
      else if (key === 'wrapBlend') { preset_wrapBlend = value; sm_wrapBlend = value; }
      else if (key === 'noiseStrength') { preset_noiseStrength = value; sm_noiseStrength = value; }
      else if (key === 'noiseScale') { preset_noiseScale = value; sm_noiseScale = value; }
      else if (key === 'fractalIterations') sm_fractalIterations = value;
      else if (['exposure','contrast','highlights','shadows','blacks','texture','clarity','dehaze','vibrance','saturation'].includes(key)) {

      }
      else if (key === 'aaLevel') aaLevel = value;
      else if (key === 'tileMethod')  tileMethod = value;
		else if (key === 'foldAngle') { sm_foldAngle = value; }
      else if (key === 'foldCount') { sm_foldCount = value; }
      else if (key === 'sphericalAmount') { sm_sphericalAmount = value; }
      else if (key === 'swirlStrength') { sm_swirlStrength = value; }
      else if (key === 'polarPower') { sm_polarPower = value; }
      else if (key === 'horseshoeAmount') { sm_horseshoeAmount = value; }
    } else {

    }
  }

  const defaultZoom = 1.73;
  let targetZoom = loadedKeys.has('zoomFactor')
                   ? preset.params.zoomFactor
                   : defaultZoom;
  zoomFactor = targetZoom;
  sm_zoomFactor = targetZoom;

  ['fractalOffset','rotationAngle','warpIntensity','rotationVariation']
    .forEach(key => {
      let springInst, setter;
      if (key==='fractalOffset')      { springInst = offsetSpring; setter = v=>sm_fractalOffset = v; }
      else if (key==='rotationAngle') { springInst = rotationSpring; setter = v=>sm_rotationAngle = v; }
      else if (key==='warpIntensity'){ springInst = warpSpring;     setter = v=>sm_warpIntensity = v; }
      else if (key==='rotationVariation'){ springInst = rotationVarSpring; setter = v=>sm_rotationVariation = v; }

      var val = loadedKeys.has(key) ? preset.params[key] : window[key];
      window[key] = val;
      springInst.position = val;
      springInst.velocity = 0;
      setter(val);
      updateOPCControl(key, val);
    });

  if (!advancedFeaturesUnlocked) {
    fractalScale   = preset_fractalScale;
    scaleVariation = preset_scaleVariation;
    wrapBlend      = preset_wrapBlend;
    noiseStrength  = preset_noiseStrength;
    noiseScale     = preset_noiseScale;
    sm_fractalScale   = preset_fractalScale;
    sm_scaleVariation = preset_scaleVariation;
    sm_wrapBlend      = preset_wrapBlend;
    sm_noiseStrength  = preset_noiseStrength;
    sm_noiseScale     = preset_noiseScale;
    ['fractalScale','scaleVariation','wrapBlend','noiseStrength','noiseScale']
      .forEach(p=> updateOPCControl(p, eval(p)));
  }

	  const newParameterDefaults = {
    foldAngle: 0.0,
    foldCount: 1,
    sphericalAmount: 0.0,
    swirlStrength: 0.0,
    polarPower: 1.0,
    horseshoeAmount: 0.0
  };

  for (let param in newParameterDefaults) {
    if (!loadedKeys.has(param)) {
      let defaultVal = newParameterDefaults[param];
      window[param] = defaultVal;
      updateOPCControl(param, defaultVal);
      switch(param) {
        case 'foldAngle': sm_foldAngle = defaultVal; break;
        case 'foldCount': sm_foldCount = defaultVal; break;
        case 'sphericalAmount': sm_sphericalAmount = defaultVal; break;
        case 'swirlStrength': sm_swirlStrength = defaultVal; break;
        case 'polarPower': sm_polarPower = defaultVal; break;
        case 'horseshoeAmount': sm_horseshoeAmount = defaultVal; break;
      }
    }
  }


  isApplyingPreset = false;             
}

function draw() {
  let nowTime = millis();
  if (lastTime === null) lastTime = nowTime;
  let dt = (nowTime - lastTime) / 1000;
  lastTime = nowTime;

  if (animateMode && amplitude) {
    let level = amplitude.getLevel();
    let audioFactor = constrain(level * 10, 0, 1);
    let t = millis() / 1000.0;
    fractalOffset = lerp(fractalOffset, baseFractalOffset + audioFactor * (0.2 * sin(t * 0.5) + 0.1 * (noise(t * 0.3) - 0.5)), 0.05);
    rotationAngle = lerp(rotationAngle, baseRotationAngle + audioFactor * (0.3 * sin(t * 0.8) + 0.2 * sin(t * 2.0)), 0.05);
    warpIntensity = lerp(warpIntensity, baseWarpIntensity + audioFactor * (0.3 * sin(t * 0.6) + 0.1 * (noise(t * 0.7) - 0.5)), 0.05);
    rotationVariation = lerp(rotationVariation, baseRotationVariation + audioFactor * (map(sin(t * 0.5), -1, 1, -0.05, 0.05)), 0.05);
  }

  if (mathModal.style("display") === "block") {
    mathContent.elt.value = generateMathString();
  }

  sm_zoomFactor = lerp(sm_zoomFactor, zoomFactor, 0.25);

  sm_fractalOffset = offsetSpring.update(fractalOffset, dt);
  sm_rotationAngle = rotationSpring.update(rotationAngle, dt);
  sm_warpIntensity = warpSpring.update(warpIntensity, dt);
  sm_rotationVariation = rotationVarSpring.update(rotationVariation, dt);

  const SPEED_LIMIT = 0.5;             
  const LIGHTING_SPEED_LIMIT = 5.0;    

  const NOISE_SPEED_LIMIT = 3;       

  sm_fractalScale = limitedLerp(sm_fractalScale, advancedFeaturesUnlocked ? fractalScale : preset_fractalScale, SPEED_LIMIT * dt);
  sm_scaleVariation = limitedLerp(sm_scaleVariation, advancedFeaturesUnlocked ? scaleVariation : preset_scaleVariation, SPEED_LIMIT * dt);
  sm_wrapBlend = limitedLerp(sm_wrapBlend, advancedFeaturesUnlocked ? wrapBlend : preset_wrapBlend, SPEED_LIMIT * dt);

  sm_noiseStrength = limitedLerp(sm_noiseStrength, advancedFeaturesUnlocked ? noiseStrength : preset_noiseStrength, NOISE_SPEED_LIMIT * dt);
  sm_noiseScale = limitedLerp(sm_noiseScale, advancedFeaturesUnlocked ? noiseScale : preset_noiseScale, NOISE_SPEED_LIMIT * dt);

  sm_fractalIterations = fractalIterations; 

  sm_exposure = limitedLerp(sm_exposure, exposure, LIGHTING_SPEED_LIMIT * dt);
  sm_contrast = limitedLerp(sm_contrast, contrast, LIGHTING_SPEED_LIMIT * dt);
  sm_highlights = limitedLerp(sm_highlights, highlights, LIGHTING_SPEED_LIMIT * dt);
  sm_shadows = limitedLerp(sm_shadows, shadows, LIGHTING_SPEED_LIMIT * dt);
  sm_blacks = limitedLerp(sm_blacks, blacks, LIGHTING_SPEED_LIMIT * dt);
  sm_texture = limitedLerp(sm_texture, texture, LIGHTING_SPEED_LIMIT * dt);
  sm_clarity = limitedLerp(sm_clarity, clarity, LIGHTING_SPEED_LIMIT * dt);
  sm_dehaze = limitedLerp(sm_dehaze, dehaze, LIGHTING_SPEED_LIMIT * dt);
  sm_vibrance = limitedLerp(sm_vibrance, vibrance, LIGHTING_SPEED_LIMIT * dt);
  sm_saturation = limitedLerp(sm_saturation, saturation, LIGHTING_SPEED_LIMIT * dt);
const NEW_PARAM_SPEED = 3.0;
  sm_foldAngle = limitedLerp(sm_foldAngle, foldAngle, NEW_PARAM_SPEED * dt);
  sm_foldCount = foldCount;
  sm_sphericalAmount = limitedLerp(sm_sphericalAmount, sphericalAmount, NEW_PARAM_SPEED * dt);
  sm_swirlStrength = limitedLerp(sm_swirlStrength, swirlStrength, NEW_PARAM_SPEED * dt);
  sm_polarPower = limitedLerp(sm_polarPower, polarPower, NEW_PARAM_SPEED * dt);
  sm_horseshoeAmount = limitedLerp(sm_horseshoeAmount, horseshoeAmount, NEW_PARAM_SPEED * dt);

  let targetColor1 = hexToRgb(color1);
  let targetColor2 = hexToRgb(color2);
  let targetBgColor = hexToRgb(bgColor);
  for (let i = 0; i < 3; i++) {
    sm_color1[i] = limitedLerp(sm_color1[i], targetColor1[i], SPEED_LIMIT * dt);
    sm_color2[i] = limitedLerp(sm_color2[i], targetColor2[i], SPEED_LIMIT * dt);
    sm_bgColor[i] = limitedLerp(sm_bgColor[i], targetBgColor[i], SPEED_LIMIT * dt);
  }

  if (aaLevel !== lastAALevel) {
    if (pg) { pg.remove(); pg = null; }
    if (aaLevel > 0) {
      pg = createGraphics(windowWidth * aaLevel, windowHeight * aaLevel, WEBGL);
      pg.pixelDensity(1);
      pg.noStroke();
      offscreenShader = pg.createShader(vertShader, fragShader);
    }
    lastAALevel = aaLevel;
  }

  if (aaLevel > 0 && pg) {
    pg.shader(offscreenShader);
    setShaderUniforms(offscreenShader, [pg.width, pg.height]);
    drawFullscreenTriangles(pg, true);
    pg.resetShader();

    resetShader();
    image(pg, -width / 2, -height / 2, width, height);
  } else {
    shader(mainShader);
    setShaderUniforms(mainShader, [width, height]);
    drawFullscreenTriangles(this, false);
    resetShader();
  }

}

function parameterChanged(variableName, value) {

  if (variableName === 'tileMethod') {
    const methodIndex = Number(value);
    var filename = tileMethodPresetFiles[methodIndex];

    if (!isApplyingPreset && filename && !tileMethodConfirmVisible && methodIndex !== lastSelectedTileMethod) {

      lastSelectedTileMethod = methodIndex; 
      showTileMethodConfirm(methodIndex);
      return; 
    } else {

      lastSelectedTileMethod = methodIndex;
    }
  }

  if (variableName === 'advancedFeaturesUnlocked') {
    advancedFeaturesUnlocked = value;

    if (!advancedFeaturesUnlocked) {

      fractalScale   = preset_fractalScale;
      scaleVariation = preset_scaleVariation;
      wrapBlend      = preset_wrapBlend;
      noiseStrength  = preset_noiseStrength;
      noiseScale     = preset_noiseScale;

      sm_fractalScale   = preset_fractalScale;
      sm_scaleVariation = preset_scaleVariation;
      sm_wrapBlend      = preset_wrapBlend;
      sm_noiseStrength  = preset_noiseStrength;
      sm_noiseScale     = preset_noiseScale;

      updateOPCControl('fractalScale',   preset_fractalScale);
      updateOPCControl('scaleVariation', preset_scaleVariation);
      updateOPCControl('wrapBlend',      preset_wrapBlend);
      updateOPCControl('noiseStrength',  preset_noiseStrength);
      updateOPCControl('noiseScale',     preset_noiseScale);
    }
    return;
  }

}

function updateOPCControl(variableName, value) {
    let elem = document.querySelector(`[data-opc-variable="${variableName}"]`);
    if (elem) {
        if (elem.type === 'checkbox' || elem.type === 'radio') {

           if (typeof value === 'boolean') {
              elem.checked = value;
           } else {

              let radio = document.querySelector(`[data-opc-variable="${variableName}"][value="${value}"]`);
              if (radio) radio.checked = true;
           }
        } else if (elem.tagName === 'SELECT') {
            elem.value = value;

        }
         else { 
            elem.value = value;

             if (elem.type === 'color') {

                 elem.dispatchEvent(new Event('input', { bubbles: true }));
             } else if (elem.type === 'range' || elem.type === 'number'){

                 elem.dispatchEvent(new Event('input', { bubbles: true }));
             }
        }
    } else {

    }
}

function mouseDragged() {
  if (presetManagerDragging && presetManagerDiv) {

    let newX = constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - presetManagerOffsetX, 0, windowWidth - presetManagerDiv.elt.offsetWidth);
    let newY = constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - presetManagerOffsetY, 0, windowHeight - presetManagerDiv.elt.offsetHeight);
    presetManagerDiv.position(newX, newY);

    return false;
  }

  return true;
}

function mouseReleased() {

  if (presetManagerDragging) {
    presetManagerDragging = false; 

    try {
       var topBar = select('#presetManager > div:first-child'); 
       if (topBar) {
         topBar.style("cursor", "grab");
       }
    } catch (e) {

    }
  }

  return true;
}

function windowResized(){
  resizeCanvas(windowWidth,windowHeight);
  if(pg&&aaLevel>0) pg.resizeCanvas(windowWidth*aaLevel,windowHeight*aaLevel);
}

function hexToRgb(hex){
  hex=hex.replace("#",""); let bigint=parseInt(hex,16);
  return[((bigint>>16)&255)/255,((bigint>>8)&255)/255,(bigint&255)/255];
}

function updateOPCButtonText(variableName,newText){
  var elem=document.querySelector('[data-opc-variable="'+variableName+'"]');
  if(elem) elem.innerText=newText;
}

function mouseWheel(event){
  if((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))<100)return; const now=millis(); if(now-lastWheelTime<50)return false;
  lastWheelTime=now; const stepFactor=1.1; if(event.delta>0){zoomFactor*=stepFactor;}else if(event.delta<0){zoomFactor/=stepFactor;}
  zoomFactor=constrain(zoomFactor,0.1,10); return false;
}

function keyPressed(){
  if(keyCode===9){
    presetManagerVisible=!presetManagerVisible;
    if(presetManagerDiv) presetManagerDiv.style('display',presetManagerVisible?'block':'none');
    return false;
  }
}

const vertShader=`
  precision mediump float;
  attribute vec3 aPosition;
  attribute vec2 aTexCoord;
  varying vec2 vTexCoord;
  void main(){
    vTexCoord=aTexCoord;
    gl_Position=vec4(aPosition,1.0);
  }
`;

const fragShader=`
  precision mediump float;
  #define PI 3.14159265358979323846
  uniform vec2 uResolution;
  uniform float uZoom,uFractalScale,uFractalIterations,uFractalOffset,uRotation,uWarpIntensity,uRotationVariation,
                uScaleVariation,uWrapBlend,uNoiseStrength,uNoiseScale,uExposure,uContrast,uHighlights,uShadows,
                uBlacks,uTexture,uClarity,uDehaze,uVibrance,uSaturation,uTileMethod,uSpiralFactor,
                uFoldAngle,uFoldCount,uSphericalAmount,uSwirlStrength,uPolarPower,uHorseshoeAmount;
  uniform vec3 uColor1,uColor2,uBgColor;
  varying vec2 vTexCoord;

  vec2 cMul(vec2 a,vec2 b){return vec2(a.x*b.x - a.y*b.y,a.x*b.y + a.y*b.x);}
  float rand(vec2 co){return fract(sin(dot(co,vec2(12.9898,78.233)))*43758.5453);}
  float noise(vec2 st){
    vec2 i=floor(st),f=fract(st);
    float a=rand(i),b=rand(i+vec2(1.0,0.0)),c=rand(i+vec2(0.0,1.0)),d=rand(i+vec2(1.0,1.0));
    vec2 u=f*f*(3.0-2.0*f);
    return mix(a,b,u.x)+(c-a)*u.y*(1.0-u.x)+(d-b)*u.x*u.y;
  }
  float periodicMap(float x){return(2.0/PI)*asin(sin(PI*x/2.0));}
  vec2 periodicMap2(vec2 p){return vec2(periodicMap(p.x),periodicMap(p.y));}
  vec2 hexTiling(vec2 p){
    float q=(1.73205/3.0)*p.x-(1.0/3.0)*p.y;float r=(2.0/3.0)*p.y;
    float rq=floor(q+0.5),rr=floor(r+0.5);
    vec2 hc=vec2(1.73205*rq+(1.73205/2.0)*rr,1.5*rr);return p-hc;
  }
  vec2 triangularTiling(vec2 p){
    const float a=1.0;const float h=0.8660254;
    vec2 q=mod(p,vec2(a,h));if(q.x+q.y/h>1.0){q=vec2(a,h)-q;}return q-vec2(a/2.0,h/2.0);
  }
  vec2 spiralTiling(vec2 p){
    float r=length(p);float theta=atan(p.y,p.x);theta+=log(max(r,0.0001))*uSpiralFactor;
    return vec2(r*cos(theta),r*sin(theta));
  }

  vec2 applyFold(vec2 p, float foldAngle, float foldCount){
    if(foldCount < 1.5) return p;
    float r = length(p);
    if(r < 0.0001) return p;
    float theta = atan(p.y, p.x);
    float segment = 2.0 * PI / foldCount;
    theta = theta + foldAngle;
    theta = mod(theta + PI * 10.0, segment);
    if(theta > segment * 0.5) theta = segment - theta;
    return vec2(r * cos(theta), r * sin(theta));
  }

  vec2 applySpherical(vec2 p, float amount){
    if(amount < 0.001) return p;
    float r2 = dot(p, p);
    if(r2 < 0.0001) r2 = 0.0001;
    vec2 spherical = p / r2;
    return mix(p, spherical, amount);
  }

  vec2 applySwirl(vec2 p, float strength){
    if(strength < 0.001) return p;
    float r = length(p);
    float r2 = r * r;
    float sinR2 = sin(r2 * strength * 10.0);
    float cosR2 = cos(r2 * strength * 10.0);
    return vec2(p.x * sinR2 - p.y * cosR2, p.x * cosR2 + p.y * sinR2);
  }

  vec2 applyPolarPower(vec2 p, float power){
    if(abs(power - 1.0) < 0.001) return p;
    float r = length(p);
    if(r < 0.0001) return p;
    float theta = atan(p.y, p.x);
    r = pow(r, power);
    return vec2(r * cos(theta), r * sin(theta));
  }

  vec2 applyHorseshoe(vec2 p, float amount){
    if(amount < 0.001) return p;
    float r = length(p);
    if(r < 0.0001) return p;
    vec2 horseshoe = (1.0 / r) * vec2((p.x - p.y) * (p.x + p.y), 2.0 * p.x * p.y);
    return mix(p, horseshoe, amount);
  }

  void main(){
    vec2 center=uResolution*0.5;
    vec2 uv=(gl_FragCoord.xy-center)/uResolution.y; uv*=uZoom; vec2 p=uv;
    float accIntensity=0.0;int n=int(uFractalIterations);
    for(int i=0;i<20;i++){
      if(i>=n)break;

      p = applyFold(p, uFoldAngle, uFoldCount);

      p=vec2(abs(p.x),abs(p.y));
      float ds=uFractalScale*(1.0+uScaleVariation*float(i));p*=ds;
      if(uTileMethod<0.5){
        vec2 modP=mod(p,2.0)-1.0;vec2 mirrorP=abs(mod(p,2.0)-1.0)*2.0-1.0;
        float blendX=smoothstep(0.9,1.0,abs(modP.x)),blendY=smoothstep(0.9,1.0,abs(modP.y));
        float blendFactor=max(blendX,blendY)*uWrapBlend;
        p=mix(modP,mirrorP,blendFactor);
      }else if(uTileMethod<1.5){
        vec2 modP=abs(mod(p,2.0)-1.0)*2.0-1.0;vec2 altP=vec2(sin(modP.x*PI*0.5),sin(modP.y*PI*0.5));
        p=mix(modP,altP,uWrapBlend);
      }else if(uTileMethod<2.5){
        p=p;
      }else if(uTileMethod<3.5){
        p=periodicMap2(p);
      }else if(uTileMethod<4.5){
        p=hexTiling(p);
      }else if(uTileMethod<5.5){
        p=triangularTiling(p);
      }else if(uTileMethod<6.5){
        p=spiralTiling(p);
      }

      p = applySpherical(p, uSphericalAmount);
      p = applySwirl(p, uSwirlStrength);
      p = applyPolarPower(p, uPolarPower);
      p = applyHorseshoe(p, uHorseshoeAmount);

      float d=uRotation*(1.0+uRotationVariation*float(i));
      p=cMul(p,vec2(cos(d),sin(d)));
      p+=vec2(uFractalOffset,uFractalOffset);
      p=mix(p,vec2(sin(p.x),sin(p.y)),uWarpIntensity);
      vec2 noiseVec=vec2(noise(p*uNoiseScale),noise(p.yx*uNoiseScale));
      p+=uNoiseStrength*noiseVec;
      float cellIntensity=1.0-smoothstep(0.0,0.5,length(p));
      accIntensity+=cellIntensity;
    }
    float avgIntensity=accIntensity/float(n);
    vec3 col=mix(uColor1,uColor2,avgIntensity);
    col=mix(uBgColor,col,1.0-avgIntensity);
    col*=pow(2.0,uExposure); col=(col-0.5)*(1.0+uContrast)+0.5;
    float lum=dot(col,vec3(0.299,0.587,0.114));
    col=mix(vec3(lum),col,1.0+uSaturation);
    float maxC=max(col.r,max(col.g,col.b));
    float vibranceFactor=1.0+uVibrance*(1.0-maxC);
    col=mix(vec3(lum),col,vibranceFactor);
    col.r=mix(col.r,0.0,smoothstep(0.0,0.5,col.r)*uShadows);
    col.g=mix(col.g,0.0,smoothstep(0.0,0.5,col.g)*uShadows);
    col.b=mix(col.b,0.0,smoothstep(0.0,0.5,col.b)*uShadows);
    col.r=mix(col.r,0.0,smoothstep(0.0,0.1,col.r)*uBlacks);
    col.g=mix(col.g,0.0,smoothstep(0.0,0.1,col.g)*uBlacks);
    col.b=mix(col.b,0.0,smoothstep(0.0,0.1,col.b)*uBlacks);
    col=(col-0.5)*(1.0+uTexture*0.1)+0.5;
    col=(col-0.5)*(1.0+uClarity*0.1)+0.5;
    col=(col-0.5)*(1.0+uDehaze*0.1)+0.5;
    gl_FragColor=vec4(clamp(col,0.0,1.0),1.0);
  }
`;

